const geo = msg.metadata.geo;
if (!geo) return null;

const source = msg.metadata.source;
const connKey = "parat_bridge.connections." + msg.metadata.connection_name
    + ".clients." + source.identifier + ".client_specific";
const artifactMap = global.get(connKey + ".geo_artifact_map") || {};

const operations = [];

for (const f of (geo.added || [])) {
    operations.push({ action: "create", feature: f });
}

for (const f of (geo.removed || [])) {
    const uuid = artifactMap[f.id];
    if (uuid) {
        operations.push({ action: "delete", feature: f, wasos_uuid: uuid });
    }
}

for (const f of (geo.changed || [])) {
    const uuid = artifactMap[f.id];
    if (uuid) {
        operations.push({ action: "update", feature: f, wasos_uuid: uuid });
    } else {
        operations.push({ action: "create", feature: f });
    }
}

if (operations.length === 0) return null;

msg._artifact_connKey = connKey;
msg.payload = operations;

return msg;

const op = msg.payload;
const target = msg.metadata.target;
const baseUrl = global.get("parat_bridge").base_urls.wasos;
const chatroomName = target.client_specific.chatroom_name;

msg.headers = {
    "x-api-key": target.api_key,
    "Content-Type": "application/json"
};

const artifact = {
    geom: op.feature.geometry,
    definedShapeName: "[" + msg.metadata.source.client_system + " - "
        + (msg.metadata.source.name || msg.metadata.source.client_specific?.log_name || "Ukjent")
        + "] " + (op.feature.name || ""),
    artifactType: "drawing",
    additionalInfo: op.feature.id,    // ← Rayvn feature ID for reconciliation                                                                                                                   
    axisStyle: {
        color: op.feature.color || "#337ab7",
        fillColor: op.feature.color || "#337ab7",
        fillOpacity: 0.2,
        opacity: 1,
        weight: 3
    },
    groups: [chatroomName],
    owners: []
};

if (op.action === "create") {
    msg.method = "POST";
    msg.url = baseUrl + "/api/geo/artifacts";
    msg.payload = artifact;
} else if (op.action === "update") {
    msg.method = "PUT";
    msg.url = baseUrl + "/api/geo/artifacts/" + op.wasos_uuid;
    msg.payload = artifact;
} else if (op.action === "delete") {
    msg.method = "DELETE";
    msg.url = baseUrl + "/api/geo/artifacts/" + op.wasos_uuid;
    msg.payload = {};
}

msg._operation = op;

return msg;

const op = msg._operation;
const connKey = msg._artifact_connKey;
const statusCode = msg.statusCode;

if (op.action === "create" && (statusCode === 200 || statusCode === 201)) {
    const uuid = msg.payload?.uuid;
    if (uuid) {
        const map = global.get(connKey + ".geo_artifact_map") || {};
        map[op.feature.id] = uuid;
        global.set(connKey + ".geo_artifact_map", map);
        msg._artifact_preview = { uuid: uuid, name: op.feature.name, action: "create" };
        node.status({
            fill: "green", shape: "dot",
            text: "+" + op.feature.name + " " + new Date().toLocaleTimeString()
        });
    }
} else if (op.action === "delete" && (statusCode === 200 || statusCode === 204)) {
    const map = global.get(connKey + ".geo_artifact_map") || {};
    delete map[op.feature.id];
    global.set(connKey + ".geo_artifact_map", map);
    node.status({
        fill: "yellow", shape: "ring",
        text: "-" + op.feature.name + " " + new Date().toLocaleTimeString()
    });
} else if (op.action === "update" && statusCode === 200) {
    msg._artifact_preview = { uuid: op.wasos_uuid, name: op.feature.name, action: "update" };
    node.status({
        fill: "blue", shape: "dot",
        text: "~" + op.feature.name + " " + new Date().toLocaleTimeString()
    });
} else {
    node.warn("[BOOST] Artifact " + op.action + " failed: " + statusCode
        + " for feature " + (op.feature.name || op.feature.id));
}

return msg;
